const DT = 1 / 60;
let prev = 0, lag = 0;
function frame(ts) {                       // ts: end of the previous frame (ms)
  if (prev !== 0) {
    lag += (ts - prev) / 1000;             // seconds; never a frame counter
    if (lag > 0.25) lag = 0.25;            // clamp (tab pause, GC hitch)
    while (lag >= DT) { step(DT); lag -= DT; }
    render(lag / DT);                      // interpolate previous -> current
  }
  prev = ts;
  requestAnimationFrame(frame);            // one-shot: re-arm every frame
}
requestAnimationFrame(frame);

